ate<Long> finishTime;\n\n        public SessionTrackingFunction(long sessionGapMicros) {\n            this.sessionGapMicros = sessionGapMicros;\n        }\n\n        @Override\n        public void open(org.apache.flink.configuration.Configuration parameters) {\n            lastSubmitTs = getRuntimeContext().getState(\n                    new ValueStateDescriptor<>(\"lastSubmitTs\", Long.class));\n            currentStageCount = getRuntimeContext().getState(\n                    new ValueStateDescriptor<>(\"currentStageCount\", Integer.class));\n            maxStageCount = getRuntimeContext().getState(\n                    new ValueStateDescriptor<>(\"maxStageCount\", Integer.class));\n            finishTime = getRuntimeContext().getState(\n                    new ValueStateDescriptor<>(\"finishTime\", Long.class));\n        }\n\n        @Override\n        public void processElement1(TaskEvent task, Context ctx,\n                                    Collector<Tuple2<Long, Integer>> out) throws Exception {\n            Long lastTs = lastSubmitTs.value();\n            Integer curr = currentStageCount.value();\n            Integer max = maxStageCount.value();\n            if (max == null) max = 0;\n\n            if (lastTs == null || task.time - lastTs > sessionGapMicros) {\n                if (curr != null && curr > max) {\n                    max = curr;\n                }\n                curr = 1;\n            } else {\n                curr = (curr == null ? 1 : curr + 1);\n            }\n\n            lastSubmitTs.update(task.time);\n            currentStageCount.update(curr);\n            maxStageCount.update(max);\n        }\n\n        @Override\n        public void processElement2(JobEvent job, Context ctx,\n                                    Collector<Tuple2<Long, Integer>> out) throws Exception {\n            // Defer emission until the watermark has passed the FINISH time to\n            // guarantee that every SUBMIT event up to that point is applied.\n     